// The native video surface for the iPad player (see src/mpv_ios.rs).
//
// mpv renders into a CAMetalLayer that sits directly under the WKWebView, and
// the webview is made transparent so Harbor's own player controls and
// subtitles draw over the video. The CI build adds this file to the Xcode
// target generated by `tauri ios init`; Rust reaches it through @_cdecl.

import AVFoundation
import QuartzCore
import UIKit
import WebKit

/// MoltenVK briefly sets drawableSize to 1x1 to force a present, which
/// flickers and can leave the layer stuck at that size
/// (https://github.com/mpv-player/mpv/pull/13651). EDR has to be switched on
/// the main thread or the display never enters HDR mode.
final class HarborMetalLayer: CAMetalLayer {
    override var drawableSize: CGSize {
        get { super.drawableSize }
        set {
            if Int(newValue.width) > 1 && Int(newValue.height) > 1 {
                super.drawableSize = newValue
            }
        }
    }

    override var wantsExtendedDynamicRangeContent: Bool {
        get { super.wantsExtendedDynamicRangeContent }
        set {
            if Thread.isMainThread {
                super.wantsExtendedDynamicRangeContent = newValue
            } else {
                DispatchQueue.main.sync { super.wantsExtendedDynamicRangeContent = newValue }
            }
        }
    }
}

final class HarborVideoView: UIView {
    override class var layerClass: AnyClass { HarborMetalLayer.self }

    override func layoutSubviews() {
        super.layoutSubviews()
        let scale = window?.screen.nativeScale ?? UIScreen.main.nativeScale
        layer.contentsScale = scale
    }
}

private var videoView: HarborVideoView?

private func webView(from pointer: UnsafeMutableRawPointer) -> WKWebView {
    Unmanaged<WKWebView>.fromOpaque(pointer).takeUnretainedValue()
}

/// Creates the surface (once) under the webview and returns the layer pointer
/// for mpv's `wid` option, or 0 if the webview is not in a view hierarchy yet.
@_cdecl("harbor_ios_video_attach")
public func harbor_ios_video_attach(_ pointer: UnsafeMutableRawPointer) -> Int64 {
    let web = webView(from: pointer)
    guard let host = web.superview else { return 0 }

    // Without the playback category the ring/silent switch mutes the video.
    try? AVAudioSession.sharedInstance().setCategory(.playback, mode: .moviePlayback)
    try? AVAudioSession.sharedInstance().setActive(true)

    web.isOpaque = false
    web.backgroundColor = .clear
    web.scrollView.backgroundColor = .clear

    let view: HarborVideoView
    if let existing = videoView, existing.superview === host {
        view = existing
    } else {
        videoView?.removeFromSuperview()
        view = HarborVideoView(frame: web.frame)
        view.backgroundColor = .black
        view.isUserInteractionEnabled = false
        view.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        if let metal = view.layer as? CAMetalLayer {
            metal.framebufferOnly = true
            metal.backgroundColor = UIColor.black.cgColor
        }
        host.insertSubview(view, belowSubview: web)
        videoView = view
    }
    view.isHidden = false
    view.layer.contentsScale = host.window?.screen.nativeScale ?? UIScreen.main.nativeScale
    return Int64(Int(bitPattern: Unmanaged.passUnretained(view.layer).toOpaque()))
}

/// Moves the surface to the player's stage. The rect is in CSS pixels, which
/// WKWebView maps 1:1 to points at the default zoom.
@_cdecl("harbor_ios_video_set_frame")
public func harbor_ios_video_set_frame(
    _ pointer: UnsafeMutableRawPointer, _ x: Double, _ y: Double, _ w: Double, _ h: Double
) {
    guard let view = videoView, let host = view.superview, w > 1, h > 1 else { return }
    let web = webView(from: pointer)
    view.autoresizingMask = []
    view.frame = web.convert(CGRect(x: x, y: y, width: w, height: h), to: host)
}

/// Hides the surface between titles. The layer is kept so the next mpv
/// session can reuse it without the webview flashing.
@_cdecl("harbor_ios_video_detach")
public func harbor_ios_video_detach() {
    videoView?.isHidden = true
}
